
const WORDS=[{"id": 0, "w": "纸上谈兵", "p": "zhǐshàng tánbīng", "t": "成语", "m": "bàn chuyện đánh giặc trên giấy (lý luận suông)", "coll": "不能纸上谈兵、避免纸上谈兵", "s": "学到的理论要用到实际中去，不能只是纸上谈兵。"}, {"id": 1, "w": "军事", "p": "jūnshì", "t": "名词", "m": "việc quân", "coll": "军事历史、军事知识", "s": "他对军事历史很感兴趣，经常阅读相关书籍。"}, {"id": 2, "w": "敌人", "p": "dírén", "t": "名词", "m": "quân địch", "coll": "面对敌人、故事中的敌人", "s": "故事中的主人公为了保护家乡，勇敢地面对敌人。"}, {"id": 3, "w": "理论", "p": "lǐlùn", "t": "名词", "m": "lý luận, lý thuyết", "coll": "学习理论、理论与实践", "s": "学习理论的同时，我们也要重视实践。"}, {"id": 4, "w": "作战", "p": "zuòzhàn", "t": "动词", "m": "đánh giặc, chiến đấu", "coll": "英勇作战、历史上的作战经历", "s": "这本书讲述了一位老兵过去的作战经历。"}, {"id": 5, "w": "毛病", "p": "máobìng", "t": "名词", "m": "khuyết điểm, tật xấu", "coll": "改掉毛病、小毛病", "s": "他下定决心，要改掉拖拉的毛病。"}, {"id": 6, "w": "道理", "p": "dàolǐ", "t": "名词", "m": "lý lẽ, lý thuyết", "coll": "讲道理、明白道理", "s": "听了老师的话，他终于明白了这个道理。"}, {"id": 7, "w": "迟早", "p": "chízǎo", "t": "副词", "m": "sớm muộn", "coll": "迟早会、迟早成功", "s": "只要坚持努力，你迟早会取得进步。"}, {"id": 8, "w": "军队", "p": "jūnduì", "t": "名词", "m": "quân đội", "coll": "一支军队、军队的历史", "s": "这部纪录片介绍了一支军队的历史。"}, {"id": 9, "w": "派", "p": "pài", "t": "动词", "m": "phái đi, cử đi", "coll": "派人、派代表", "s": "学校决定派几名学生参加这次交流活动。"}, {"id": 10, "w": "弱", "p": "ruò", "t": "形容词", "m": "yếu, kém", "coll": "身体弱、能力较弱", "s": "他小时候身体比较弱，经常请假。"}, {"id": 11, "w": "形势", "p": "xíngshì", "t": "名词", "m": "tình hình", "coll": "当前形势、分析形势", "s": "开会时，大家认真分析了当前的形势。"}, {"id": 12, "w": "命令", "p": "mìnglìng", "t": "动词／名词", "m": "ra lệnh; mệnh lệnh", "coll": "下达命令、执行命令", "s": "故事里，国王命令大家立刻离开危险的地方。"}, {"id": 13, "w": "守", "p": "shǒu", "t": "动词", "m": "phòng thủ, trấn giữ", "coll": "守住大门、守在门口", "s": "小狗一直守在门口，等着主人回来。"}, {"id": 14, "w": "阵地", "p": "zhèndì", "t": "名词", "m": "trận địa, mặt trận", "coll": "坚守阵地、守住阵地", "s": "故事中的士兵们在困难面前仍然坚守着阵地。"}, {"id": 15, "w": "绝对", "p": "juéduì", "t": "形容词／副词", "m": "tuyệt đối; nhất định", "coll": "绝对不能、绝对相信", "s": "这件事关系到大家的安全，绝对不能马虎。"}, {"id": 16, "w": "主动", "p": "zhǔdòng", "t": "形容词", "m": "chủ động", "coll": "主动帮助、主动参加", "s": "她经常主动帮助学习有困难的同学。"}, {"id": 17, "w": "挑战", "p": "tiǎozhàn", "t": "动词／名词", "m": "khiêu chiến, thách thức; sự thách thức", "coll": "面对挑战、接受挑战", "s": "学习一门新的语言，对他来说是一次挑战。"}, {"id": 18, "w": "骂", "p": "mà", "t": "动词", "m": "chửi, mắng", "coll": "骂人、被骂", "s": "遇到问题时，要好好沟通，不要随便骂人。"}, {"id": 19, "w": "胆小鬼", "p": "dǎnxiǎoguǐ", "t": "名词", "m": "kẻ hèn nhát", "coll": "不是胆小鬼、被叫作胆小鬼", "s": "他不愿被别人叫作胆小鬼，决定勇敢地尝试一次。"}, {"id": 20, "w": "胜利", "p": "shènglì", "t": "动词", "m": "thắng lợi", "coll": "取得胜利、庆祝胜利", "s": "经过全队的努力，我们终于取得了胜利。"}, {"id": 21, "w": "调动", "p": "diàodòng", "t": "动词", "m": "điều động, thuyên chuyển", "coll": "调动人员、调动积极性", "s": "有趣的课堂活动能够调动学生的积极性。"}, {"id": 22, "w": "散布", "p": "sànbù", "t": "动词", "m": "gieo rắc, truyền", "coll": "散布消息、散布谣言", "s": "在没有弄清事实之前，不要随便散布消息。"}, {"id": 23, "w": "谣言", "p": "yáoyán", "t": "名词", "m": "tin đồn", "coll": "相信谣言、传播谣言", "s": "听到这样的说法，我们不能轻易相信谣言。"}, {"id": 24, "w": "上当", "p": "shàng dàng", "t": "动词", "m": "bị lừa, bị mắc lừa", "coll": "小心上当、上当受骗", "s": "买东西时，要仔细辨别，小心上当。"}, {"id": 25, "w": "再三", "p": "zàisān", "t": "副词", "m": "nhiều lần, hết lần này đến lần khác", "coll": "再三提醒、再三考虑", "s": "经过再三考虑，她还是决定接受这份工作。"}, {"id": 26, "w": "阻止", "p": "zǔzhǐ", "t": "动词", "m": "ngăn cản, cản trở", "coll": "阻止别人、阻止浪费", "s": "看到有人浪费食物，他上前阻止了这种行为。"}, {"id": 27, "w": "任命", "p": "rènmìng", "t": "动词", "m": "bổ nhiệm", "coll": "任命负责人、被任命为", "s": "她被公司任命为新项目的负责人。"}, {"id": 28, "w": "独立", "p": "dúlì", "t": "动词", "m": "có một mình, không lệ thuộc", "coll": "独立生活、独立完成", "s": "从上大学开始，她就学会了独立生活。"}, {"id": 29, "w": "资格", "p": "zīgé", "t": "名词", "m": "tư cách", "coll": "具备资格、参加比赛的资格", "s": "通过这次选拔，他获得了参加比赛的资格。"}, {"id": 30, "w": "糊涂", "p": "hútu", "t": "形容词", "m": "đần độn, hồ đồ", "coll": "糊涂了、一时糊涂", "s": "我一时糊涂，把开会的日期记错了。"}, {"id": 31, "w": "公元", "p": "gōngyuán", "t": "名词", "m": "công nguyên", "coll": "公元纪年、公元一世纪", "s": "这本书介绍了公元一世纪人们的生活。"}, {"id": 32, "w": "盲目", "p": "mángmù", "t": "形容词", "m": "mù quáng", "coll": "盲目相信、盲目跟风", "s": "做决定前要认真思考，不能盲目跟风。"}, {"id": 33, "w": "轻视", "p": "qīngshì", "t": "动词", "m": "khinh thường, xem thường", "coll": "轻视对手、不能轻视", "s": "无论对方的水平怎样，我们都不能轻视对手。"}, {"id": 34, "w": "方案", "p": "fāng'àn", "t": "名词", "m": "kế hoạch, phương án", "coll": "提出方案、修改方案", "s": "大家讨论以后，提出了一个新的方案。"}, {"id": 35, "w": "进攻", "p": "jìngōng", "t": "动词", "m": "tấn công, công kích", "coll": "发起进攻、进攻对方球门", "s": "下半场开始后，这支球队加强了进攻。"}, {"id": 36, "w": "宝贵", "p": "bǎoguì", "t": "形容词", "m": "quý báu, quý giá", "coll": "宝贵的经验、宝贵的时间", "s": "这次活动给我们留下了宝贵的经验。"}, {"id": 37, "w": "讽刺", "p": "fěngcì", "t": "动词", "m": "châm biếm, mỉa mai", "coll": "讽刺别人、讽刺的语气", "s": "他说话时带着讽刺的语气，让对方觉得很不舒服。"}, {"id": 38, "w": "灵活", "p": "línghuó", "t": "形容词", "m": "linh hoạt, nhạy bén", "coll": "灵活运用、方法灵活", "s": "老师鼓励我们灵活运用学过的词语。"}];
